def tag(text, kind='neutral'):return f'<span class="tag {kind}">{e(text)}</span>'
def btn(text, primary=False):return f'<span class="btn{ " primary" if primary else ""}">{e(text)}</span>'
def field(label,value='',help='',error=False):return f'<div class="field"><label>{e(label)}</label><div class="input{ " invalid" if error else ""}">{e(value) or "&nbsp;"}</div>'+ (f'<small class="{ "error" if error else "help"}">{e(help)}</small>' if help else '')+'</div>'
def panel(title,body,change=None):return f'<section class="panel{ " changed" if change else ""}">'+(f'<span class="number">{change}</span>' if change else '')+f'<h2>{e(title)}</h2>{body}</section>'
def alert(text,kind='info'):return f'<div class="notice {kind}">{e(text)}</div>'
def row(left,right):return f'<div class="row"><div>{left}</div><div>{right}</div></div>'
def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+e(c)+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table>'
def foot(*buttons):return '<div class="footer">'+''.join(buttons)+'</div>'
def steps(items):return '<ol class="steps">'+''.join('<li>'+e(t)+'</li>' for t in items)+'</ol>'
def change(n,body):return f'<div class="changed"><span class="number">{n}</span>{body}</div>'

