review=[]
for f in findings:
    i=int(f['id'][3:]);frames,status,observed,goals=spec[i]
    record={**f,'current_status':status,'current_observation':observed,'frames':frames,'goals':goals,'target':'targets/'+f['id']+'.html'}
    if i==10:record['design_note']='尺寸600×765来自原测试素材，只表示自动识别的目标；本轮没有完成上传，不将此图作为修复证据。'
    elif i in (12,13):record['design_note']='实际业务根因或库存生成规则仍待核对；目标只示意解释与恢复路径，不预设未知原因或宣称已修复。'
    elif i==9:record['design_note']='草稿与发布必填规则需先核对现有合同；此图表达分组、完成状态和默认值，不授权删除业务校验。'
    elif i==20:record['design_note']='文件下载请求链路仍需真实修复与验证；此图分别展示可下载及下载失败时的目标状态。'
    else:record['design_note']='绿色编号对应希望调整的区域；目标是设计建议，未接入真实业务，也不是实现后的验收截图。'
    title=f['title']
    out='<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(f['id']+' 目标示意')+'</title><link rel="stylesheet" href="target.css"></head><body><header class="top"><strong>Shoppp 后台</strong><span>'+e(f['id'])+'</span><span class="watermark">目标设计示意 · 未实现</span></header><main class="canvas">'+bodies[i]+'</main><p class="footnote">静态示意：用于比较布局与状态，控件不会操作后台。</p></body></html>'
    (ROOT/record['target']).write_text(out)
    review.append(record)
(ROOT/'review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n')
(ROOT/'review-data.js').write_text('window.REVIEW_DATA = '+json.dumps(review,ensure_ascii=False)+';\n')
print('Built 25 current-review records and 25 distinct target mockups.')
